import {ToggleDashboardSidebarButton} from '@common/datatable/page/toggle-dashboard-sidebar-button';
import clsx from 'clsx';
import {ReactNode} from 'react';

interface DatatablePageWithHeaderLayoutProps {
  children: ReactNode;
  className?: string;
}
export function DatatablePageWithHeaderLayout({
  children,
  className,
}: DatatablePageWithHeaderLayoutProps) {
  return (
    <div className={clsx('flex h-full flex-col', className)}>{children}</div>
  );
}

export function DatatablePageScrollContainer({
  children,
  className,
}: {
  children: ReactNode;
  className?: string;
}) {
  return (
    <div className={clsx('flex-auto overflow-y-auto', className)}>
      {children}
    </div>
  );
}

export type BodyProps = {
  children: ReactNode;
  className?: string;
  padding?: string;
};
export function DatatablePageWithHeaderBody({
  children,
  className,
  padding = 'p-12 md:p-24',
}: BodyProps) {
  return (
    <div
      className={clsx('flex min-h-0 flex-auto flex-col', padding, className)}
    >
      {children}
    </div>
  );
}

interface DatatablePageHeaderBarProps {
  title?: ReactNode;
  children?: ReactNode;
  showSidebarToggleButton?: boolean;
  titleId?: string;
  titleMargin?: string;
  leftContent?: ReactNode;
  rightContent?: ReactNode;
  border?: string;
  padding?: string;
  className?: string;
  toggleButton?: ReactNode;
  height?: string;
}
export function DatatablePageHeaderBar({
  title,
  children,
  showSidebarToggleButton = false,
  titleId,
  leftContent,
  rightContent,
  border = 'border-b',
  height = 'h-[var(--panel-header-height,3.5rem)]',
  padding,
  className,
  toggleButton,
  titleMargin,
}: DatatablePageHeaderBarProps) {
  if (!toggleButton) {
    toggleButton = showSidebarToggleButton ? (
      <ToggleDashboardSidebarButton />
    ) : null;
  }

  const titleContent = title || children;

  return (
    <div
      className={clsx(
        'flex flex-shrink-0 items-center gap-8',
        height,
        padding
          ? padding
          : showSidebarToggleButton
            ? 'pl-8 pr-12 md:pl-20 md:pr-24'
            : 'px-12 md:px-24',
        border,
        className,
      )}
    >
      {toggleButton}
      {titleContent && (
        <h1
          id={titleId}
          className={clsx(
            'overflow-hidden overflow-ellipsis whitespace-nowrap text-xl font-semibold first:capitalize',
            // need to expand for breadcrumbs to work properly
            !leftContent && 'flex-auto',
            titleMargin ? titleMargin : 'mr-24 [&_.breadcrumb-root]:-ml-6',
          )}
        >
          {titleContent}
        </h1>
      )}
      {leftContent}
      {rightContent && (
        <div className="ml-auto flex items-center gap-8">{rightContent}</div>
      )}
    </div>
  );
}
